// Some portions generated by Claude

// @ts-check
const { test, expect } = require('@playwright/test');
const {
	deleteRepository,
	memoryRepositoryConfiguration,
	repositoryPageUrl,
	serverBaseUrl,
	uniqueRepositoryId,
	waitForRoute
} = require('./workbench-test-helpers.js');

// Round-2 review of GH-6071 (R23): a disclosure pane that opens over the content after it must take every click,
// whether its page was loaded directly or opened in place from another page.
const REPOSITORY_ID = uniqueRepositoryId('workbench-round2-disclosures');
const REPOSITORY_URL = `${serverBaseUrl()}/repositories/${encodeURIComponent(REPOSITORY_ID)}`;

test.beforeAll(async ({ request }) => {
	const created = await request.put(REPOSITORY_URL, {
		headers: { 'Content-Type': 'text/turtle' },
		data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Round 2 disclosures')
	});
	expect([200, 201, 204]).toContain(created.status());
	const loaded = await request.post(`${REPOSITORY_URL}/statements`, {
		headers: { 'Content-Type': 'text/turtle' },
		data: '<urn:a> <urn:p> "x"@en, 42 ; <urn:q> <urn:b> .'
	});
	expect([200, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

/** Opens a page through its menu link, as a person does, and waits until the router shows it. */
async function openFromMenu(page, view) {
	await page.locator(`#navigation a[href="${view}"]`).click();
	await waitForRoute(page, view, { url: (url) => url.pathname.endsWith('/' + view) });
}

/** Whether the element at the centre of the control is the control itself (or inside it): nothing covers it. */
async function topmostAtCentre(locator) {
	return locator.evaluate((element) => {
		const box = element.getBoundingClientRect();
		const hit = document.elementFromPoint(box.left + box.width / 2, box.top + box.height / 2);
		const label = element.id ? document.querySelector(`label[for="${element.id}"]`) : null;
		return {
			ok: !!hit && (hit === element || element.contains(hit) || (!!label && (hit === label || label.contains(hit)))
				|| (!!hit.closest('label') && hit.closest('label').contains(element))),
			hit: hit ? `${hit.tagName.toLowerCase()}#${hit.id}.${String(hit.className).split(' ')[0]}` : null
		};
	});
}

/** Opens a disclosure with its toggle and waits until its pane has finished opening (its height animates). */
async function openDisclosure(page, toggle) {
	await toggle.click();
	await expect(toggle).toHaveAttribute('aria-expanded', 'true');
	const panel = page.locator('#' + await toggle.getAttribute('aria-controls'));
	await expect.poll(() => panel.evaluate((element) => element.getAnimations({ subtree: true })
		.filter((animation) => animation.playState === 'running').length
		+ (element.getBoundingClientRect().height + 1 < element.scrollHeight ? 1 : 0))).toBe(0);
	return panel;
}

async function exploreDisplayWorks(page) {
	await openDisclosure(page, page.locator('#explore-result-options-toggle'));
	const datatypes = page.locator('#explore-show-datatypes');
	await expect(datatypes).toBeVisible();
	for (const control of [datatypes, page.locator('#limit_explore')]) {
		const top = await topmostAtCentre(control);
		expect(top.ok, `nothing covers ${await control.getAttribute('id')}: ${top.hit}`).toBe(true);
	}
	const before = await datatypes.isChecked();
	await datatypes.click({ timeout: 5000 });
	await expect(datatypes).toBeChecked({ checked: !before });
}

test('the Explore Display pane takes clicks on a page loaded directly', async ({ page }) => {
	await page.setViewportSize({ width: 1400, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'explore') + '?resource=' + encodeURIComponent('<urn:a>'));
	await waitForRoute(page, 'explore');
	await exploreDisplayWorks(page);
});

test('the Explore Display pane takes clicks after Explore was opened in place from the Summary', async ({ page }) => {
	await page.setViewportSize({ width: 1400, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'summary'));
	await waitForRoute(page, 'summary');
	await openFromMenu(page, 'explore');
	await page.locator('#resource').fill('<urn:a>');
	await page.locator('#resource').press('Enter');
	await waitForRoute(page, 'explore', { url: /resource=/ });
	await expect(page.locator('#explore-resource-card')).toBeVisible();
	await exploreDisplayWorks(page);
});

/**
 * Opens the disclosure and checks its pane is live: not inert, not hidden from assistive technology, and no other
 * element covers any of its controls.
 */
async function paneWorks(page, toggleSelector) {
	const toggle = page.locator(toggleSelector);
	const panel = await openDisclosure(page, toggle);
	const state = await panel.evaluate((element) => ({
		inert: !!element.inert || !!element.closest('[inert]'),
		ariaHidden: element.getAttribute('aria-hidden')
	}));
	expect(state, `${toggleSelector} opens a live pane`).toEqual({ inert: false, ariaHidden: 'false' });
	const controls = panel.locator('input:not([type="hidden"]):visible:enabled, select:visible:enabled, '
		+ 'button:visible:enabled, textarea:visible:enabled');
	const count = await controls.count();
	expect(count, `${toggleSelector} has controls`).toBeGreaterThan(0);
	for (let index = 0; index < count; index++) {
		const control = controls.nth(index);
		await control.scrollIntoViewIfNeeded();
		const top = await topmostAtCentre(control);
		expect(top.ok, `${toggleSelector}: nothing covers control ${index} (${await control.getAttribute('id')
			|| await control.getAttribute('name')}): ${top.hit}`).toBe(true);
	}
	await toggle.click();
	await expect(toggle).toHaveAttribute('aria-expanded', 'false');
}

// The same disclosure elements are reused (and bound again) when a page is rendered again in place.
test('disclosure panes stay live when their page is opened again in place', async ({ page }) => {
	await page.setViewportSize({ width: 1400, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'summary'));
	await waitForRoute(page, 'summary');

	await openFromMenu(page, 'export');
	await openFromMenu(page, 'export');
	await paneWorks(page, '#export-advanced-toggle');

	await openFromMenu(page, 'add');
	await openFromMenu(page, 'add');
	await paneWorks(page, '#add-import-settings-toggle');

	await openFromMenu(page, 'explore');
	await page.locator('#resource').fill('<urn:a>');
	await page.locator('#resource').press('Enter');
	await waitForRoute(page, 'explore', { url: /resource=/ });
	await page.locator('#resource').fill('<urn:b>');
	await page.locator('#resource').press('Enter');
	await waitForRoute(page, 'explore', { url: /urn%3Ab|urn:b/ });
	await paneWorks(page, '#explore-result-options-toggle');

	await openFromMenu(page, 'query');
	await openFromMenu(page, 'namespaces');
	await openFromMenu(page, 'query');
	await paneWorks(page, '#save-query-toggle');
	await paneWorks(page, '#query-options-toggle');

	// The result's own panes, over the rows that follow them.
	await page.locator('.CodeMirror').first().evaluate((element) => element.CodeMirror.setValue(
		'SELECT * WHERE { ?s ?p ?o }'));
	await page.locator('#exec').click();
	await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'false', { timeout: 15000 });
	await paneWorks(page, '#query-results .query-result-options-toggle');
	await paneWorks(page, '#query-results .query-result-download-toggle');
});
